 "content": "def transform(grid):
    """Fill square 2-outlines containing one centered 2 marker; color by size."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Demonstrated size -> fill-color mapping: 5x5 -> 8, 7x7 -> 4, 9x9 -> 3.
    fill_color = {5: 8, 7: 4, 9: 3}
    for top in range(h):
        for left in range(w):
            for side, color in fill_color.items():
                bottom, right = top + side - 1, left + side - 1
                if bottom >= h or right >= w:
                    continue
                if not all(grid[top][c] == 2 and grid[bottom][c] == 2
                           for c in range(left, right + 1)):
                    continue
                if not all(grid[r][left] == 2 and grid[r][right] == 2
                           for r in range(top, bottom + 1)):
                    continue
                markers = [(r, c) for r in range(top + 1, bottom)
                           for c in range(left + 1, right)
                           if grid[r][c] == 2]
                if markers != [(top + side // 2, left + side // 2)]:
                    continue
                for r in range(top + 1, bottom):
                    for c in range(left + 1, right):
                        if grid[r][c] == 0:
                            out[r][c] = color
    return out
